import type { ServingDb } from "../server/db/serving";
import { responseGate } from "../server/gates/response";
import { POLICY } from "../server/policy/config";
import type { JudgeItem } from "./judge";
import type { Label } from "./label";

/** Policy sentences that may state a timeline verbatim (spec 3.2 rule 9); they are not improvised promises. */
const POLICY_SENTENCES = [
  `La revisión toma hasta ${POLICY.disputeReviewDays} días hábiles.`,
  `A análise leva até ${POLICY.disputeReviewDays} dias úteis.`,
];

/** Case and handoff references are generated by the system's tools, not bank facts to ground. */
const REFERENCE = /\b[DH]-[A-Z0-9]{6,24}\b/g;

const CREDENTIALS = /(?<!\p{L})(?:contraseña|senha|password|clave|pin|cvv|cvc|número completo de (?:la |su )?tarjeta|número completo do cartão)(?!\p{L})/iu;

/**
 * Deterministic reference for the quality judge (problem statement: "validate a sample against human or
 * deterministic judgments"). It reuses the response gate of the system under test, with the customer's full
 * records as facts:
 * - grounded = no unsupported amount and no unknown id;
 * - language = the reply's detected language is the session language (or undetectable);
 * - tone = no improvised commitment outside policy templates and no credential request.
 */
export function deterministicLabel(item: JudgeItem, customerId: string, serving: ServingDb): Label {
  const e = item.evidence;
  const products = serving.products(customerId);
  const txs = serving.transactions(customerId, { limit: 50_000 });
  const userAmounts = (e.userMessages.join(" ").match(/\d[\d.,]*\d|\d/g) ?? []).map((raw) => Number(raw.replace(/,/g, "")));
  const amounts = [
    ...products.flatMap((p) => [{ value: p.current_balance, currency: p.currency }, ...(p.credit_limit === null ? [] : [{ value: p.credit_limit, currency: p.currency }])]),
    ...txs.flatMap((t) => [{ value: t.amount, currency: t.currency }, ...(t.amount_usd === null ? [] : [{ value: t.amount_usd, currency: "USD" }])]),
    ...userAmounts.filter(Number.isFinite).flatMap((v) => ["USD", "MXN", "COP", "ARS", "BRL"].map((currency) => ({ value: v, currency }))),
  ];
  const ids = [customerId, ...products.map((p) => p.product_id), ...txs.map((t) => t.transaction_id)];
  const reply = e.reply.replace(REFERENCE, " ");
  const check = responseGate(reply, { amounts, ids, templates: POLICY_SENTENCES }, { language: e.language, canary: "\u0000no-canary\u0000" });
  const grounded = !check.ruleIds.includes("RS_AMOUNT") && !check.ruleIds.includes("RS_ID");
  const language = !check.ruleIds.includes("RS_LANG");
  const tone = !check.ruleIds.includes("RS_COMMIT") && !CREDENTIALS.test(e.reply);
  return { grounded, language, tone, pass: grounded && language && tone };
}
